package local.ondemand;
import java.net.*;import java.io.*;import java.util.*;import org.json.*;
/** At most 1 MiB per selected video; no decoder, transfer creation or URL logging. */
class SourceProbe {
 static final int PART=512*1024;long deadline,used;int firstByteMs;long contentLength;boolean ranges;
 MediaHeader.Info inspect(SourcePolicy.Source s)throws Exception{
  long start=System.currentTimeMillis();deadline=start+9000;used=0;contentLength=0;ranges=false;
  byte[] first=read(s.url,"bytes=0-"+(PART-1),PART);MediaHeader.Info h=MediaHeader.parse(first);
  if(!h.complete&&ranges&&first.length>=8&&(MediaHeader.str(first,4,4).equals("ftyp")||MediaHeader.str(first,4,4).equals("moov")))try{MediaHeader.Info targeted=mp4Tracks(s.url,first);if(targeted!=null)h=targeted;}catch(IOException ignored){}
  int remaining=(int)Math.min(PART,2L*PART-used);if(!h.complete&&contentLength>PART&&ranges&&remaining>32){byte[] tail=read(s.url,"bytes="+Math.max(0,contentLength-remaining)+"-",remaining);for(int j=4;j+8<tail.length;j++)if(tail[j]=='m'&&tail[j+1]=='o'&&tail[j+2]=='o'&&tail[j+3]=='v'){long size=MediaHeader.u(tail,j-4,4);if(size>=8&&j-4+size<=tail.length){MediaHeader.Info last=MediaHeader.parse(Arrays.copyOfRange(tail,j-4,(int)(j-4+size)));if(last.complete){h=last;break;}}}}
  s.checkBytes=used;s.checkMs=Math.max(1,System.currentTimeMillis()-start);s.checkedAt=System.currentTimeMillis();s.connected=true;s.failedUntil=0;s.checkState="Connection reached · "+used/1024+" KiB sampled";if(contentLength>0)s.bytes=contentLength;s.apply(h);return h;
 }
 /** Skip large sample tables using declared atom offsets; only fetch each track's metadata prefix. */
 MediaHeader.Info mp4Tracks(String url,byte[] prefix)throws IOException{long at=0,moov=-1,end=0;for(int n=0;n<16&&at<contentLength;n++){byte[] b=chunk(url,prefix,at,32);if(b.length<8)return null;long size=MediaHeader.u(b,0,4);int head=8;if(size==1){size=MediaHeader.u(b,8,8);head=16;}if(size<head||size>contentLength-at)return null;if(MediaHeader.str(b,4,4).equals("moov")){moov=at+head;end=at+size;break;}at+=size;}if(moov<0)return null;MediaHeader.Info result=new MediaHeader.Info();boolean complete=true;at=moov;int count=0;while(at+8<=end&&count++<64){byte[] b=chunk(url,prefix,at,32);if(b.length<8)return null;long size=MediaHeader.u(b,0,4);if(size<8||size>end-at)return null;if(MediaHeader.str(b,4,4).equals("trak")){byte[] track=chunk(url,prefix,at,(int)Math.min(32768,size));MediaHeader.Info parsed=MediaHeader.parse(track);if(parsed.tracks.isEmpty())return null;for(MediaHeader.Track t:parsed.tracks){result.tracks.add(t);complete&=t.type!=0;}if(!parsed.codec.isEmpty())result.codec=parsed.codec;if(parsed.width>0){result.width=parsed.width;result.height=parsed.height;result.bits=parsed.bits;}result.hdr|=parsed.hdr;result.dv|=parsed.dv;result.seconds=Math.max(result.seconds,parsed.seconds);}at+=size;}result.complete=at==end&&complete&&!result.tracks.isEmpty();return result.tracks.isEmpty()?null:result;}
 byte[] chunk(String url,byte[] prefix,long offset,int length)throws IOException{if(offset>=0&&offset+length<=prefix.length)return Arrays.copyOfRange(prefix,(int)offset,(int)offset+length);if(offset<0||length<=0||used+length>2L*PART)throw new IOException("Metadata sample limit");return read(url,"bytes="+offset+"-"+(offset+length-1),length);}
 byte[] read(String address,String range,int limit)throws IOException{URL u=new URL(address);for(int redirect=0;redirect<4;redirect++){if(!"https".equals(u.getProtocol())||u.getUserInfo()!=null)throw new IOException("HTTPS source required");if(Thread.currentThread().isInterrupted()||System.currentTimeMillis()>=deadline)throw new java.net.SocketTimeoutException();HttpURLConnection c=(HttpURLConnection)u.openConnection();int remaining=(int)Math.max(1,deadline-System.currentTimeMillis());c.setInstanceFollowRedirects(false);c.setConnectTimeout(Math.min(3000,remaining));c.setReadTimeout(Math.min(2500,remaining));c.setRequestProperty("Range",range);c.setRequestProperty("Accept-Encoding","identity");c.setRequestProperty("User-Agent","PiOnDemand/0.4");try{int code=c.getResponseCode();if(code>=300&&code<400){String to=c.getHeaderField("Location");if(to==null)throw new IOException("Redirect unavailable");u=new URL(u,to);continue;}if(code!=200&&code!=206)throw new IOException("Source unavailable");String type=c.getContentType();if(type!=null&&(type.contains("text/html")||type.contains("application/json")))throw new IOException("Not a video response");String cr=c.getHeaderField("Content-Range");if(cr!=null){ranges=true;int slash=cr.lastIndexOf('/');try{contentLength=Long.parseLong(cr.substring(slash+1));}catch(Exception ignored){}}else if(contentLength==0&&code==200)contentLength=c.getContentLengthLong();try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while(out.size()<limit){if(System.currentTimeMillis()>=deadline||Thread.currentThread().isInterrupted())throw new SocketTimeoutException();n=in.read(b,0,Math.min(b.length,limit-out.size()));if(n<0)break;used+=n;out.write(b,0,n);}return out.toByteArray();}}finally{c.disconnect();}}throw new IOException("Too many redirects");}
 String checkExternalSubtitle(SourcePolicy.Source s)throws Exception{JSONArray a=s.raw.optJSONArray("subtitles");if(a==null)return "";for(int i=0;i<Math.min(5,a.length());i++){JSONObject j=a.optJSONObject(i);if(j==null||!MediaHeader.english(j.optString("lang")))continue;String name=j.optString("id")+" "+j.optString("title");boolean full=j.optBoolean("full",false)||(j.has("forced")&&!j.optBoolean("forced",true));if(!full||SourcePolicy.has(name,"forced"))continue;String url=j.optString("url");if(!url.startsWith("https://"))continue;deadline=System.currentTimeMillis()+5000;byte[] b=read(url,"bytes=0-8191",8192);String t=new String(b,java.nio.charset.StandardCharsets.UTF_8);if(SourcePolicy.has(t,"\\d{1,2}:\\d{2}:\\d{2}[,.]\\d{3}\\s*-->|WEBVTT|\\[Events\\]")){s.externalSub=url;return url;}}return "";}
}
